function resetRound() {
  snake = [...]; direction = RIGHT; nextDirection = RIGHT; score = 0;
  spawnFood();
  state = 'ready';
  hideOverlay();
  updateHud('就绪');
  render();
}

function clearTimer() { if (timerId !== null) { clearInterval(timerId); timerId = null; } }

function startTimer() { clearTimer(); timerId = setInterval(step, STEP_MS); }

function start() {
  if (state === 'running') return;      // 不叠加
  if (state === 'gameover') return;     // 只接受重开
  state = 'running';
  updateHud('进行中');
  render();
  startTimer();
}

function restart() {
  clearTimer();
  resetRound();       // state ready, hud 就绪, overlay hidden
  startTimer();       // 首步将在 step() 中 ready→running
}

function step() {
  if (state === 'gameover') return;
  if (state === 'ready') {
    state = 'running';
    updateHud('进行中');
  }
  ... move ...
}
```

