function spawnFood() {
  var occupied = {};
  for each snake: occupied[x+','+y]=true;
  var empty = [];
  for y, x if !occupied push
  if (empty.length === 0) { food = null; return false; }
  food = empty[Math.floor(Math.random()*empty.length)];
  return true;
}
```
